309	    #[test]
310	    fn zero_bytes_non_utf8_and_mixed_newlines_hashed_verbatim() {
311	        // 含零字节、非法 UTF-8 字节和 LF / CRLF / CR 三种换行；
312	        // 任何文本解码、换行转换或尾部遗漏都会改变这些字节，从而改变摘要。
313	        let data: &[u8] = b"alpha\nbeta\r\ngamma\rdelta\n\x00\xff\xfe\x80tail-without-newline";
314	        let digest = digest_reader(data).unwrap();
315	        // 独立依据：python3 hashlib.sha256 对同样 48 字节的计算结果。
316	        assert_eq!(
317	            digest.to_hex(),
318	            "879e1d6af3829ebad59012630ce80b422b1bf81dbdc2bc0c1ba940f46f2dde3c"
319	        );
