11	fn main() -> ExitCode {
12	    // 使用 args_os 而非 args：命令行参数是操作系统给出的原始字节，
13	    // 在允许非 UTF-8 文件名的系统上这类路径是合法路径，必须原样保留。
14	    let mut args = env::args_os().skip(1);
15	    match args.next() {
16	        Some(ref cmd) if cmd.as_encoded_bytes() == b"--version" && args.next().is_none() => {
17	            emit_success(b"inkseal 0.1.0\n")
18	        }
19	        Some(ref cmd) if cmd.as_encoded_bytes() == b"digest" => {
20	            let (Some(path), None) = (args.next(), args.next()) else {
21	                return emit_error(2, format!("{USAGE}\n").as_bytes());
22	            };
23	            run_digest(Path::new(&path))
24	        }
25	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest" => {
26	            let (Some(path), Some(expected), None) = (args.next(), args.next(), args.next()) else {
27	                return emit_error(
28	                    2,
29	                    format!(
30	                        "inkseal: check-digest requires exactly two arguments: <file> <digest>\n\
31	                         {USAGE}\n"
32	                    )
33	                    .as_bytes(),
34	                );
35	            };
36	            run_check_digest(Path::new(&path), &expected)
37	        }
38	        _ => {
39	            // 未知子命令（即便含有非 UTF-8 字节）等用法错误统一走这里。
40	            emit_error(2, format!("{USAGE}\n").as_bytes())
41	        }
42	    }
43	}
44	
45	fn run_digest(path: &Path) -> ExitCode {
46	    // 仅在输出错误信息时做损失性转换；打开文件始终使用原始路径，
47	    // 绝不把用于显示的文字当作实际路径访问。
48	    let display = path_display(path);
49	    let file = match File::open(path) {
50	        Ok(file) => file,
51	        Err(err) => {
52	            return emit_error(
53	                1,
54	                format!("inkseal: cannot open '{display}': {err}\n").as_bytes(),
55	            );
56	        }
57	    };
58	    match inkseal::digest_reader(file) {
59	        Ok(digest) => {
60	            let mut line = digest.to_hex();
61	            line.push('\n');
62	            emit_success(line.as_bytes())
63	        }
64	        Err(err) => emit_error(
65	            1,
66	            format!("inkseal: cannot read '{display}': {err}\n").as_bytes(),
67	        ),
68	    }
69	}
70	
71	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
72	///
73	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
74	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
75	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
76	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
77	///
