/// 失败提示本身绝不能再崩溃。
#[cfg(unix)]
fn write_stderr_all(message: &[u8]) -> io::Result<()> {
    const STDERR_FD: std::os::fd::RawFd = 2;
    write_fd_all(STDERR_FD, message, "standard error")
}

/// 非 Unix 目标：沿用加锁写入并显式刷新；写失败同样由调用方忽略。
#[cfg(not(unix))]
fn write_stderr_all(message: &[u8]) -> io::Result<()> {
    write_locked_all(io::stderr().lock(), message)
}

