812	// ── 标准错误写入失败 ─────────────────────────────────────────────────────────
813	//
814	// 用户把标准错误接到另一个程序，而接收方提前关闭管道时，失败提示本身可能
815	// 写不出去。提示说明的是已经发生的失败：无论标准错误是否还可读，命令对
816	// 本次操作的判断（退出码 1 或 2）都不能改变，更不能因 eprintln! 在
817	// EPIPE/EBADF 上 panic 而以 101 崩溃。
818	#[cfg(unix)]
819	mod stderr_failures {
820	    use super::*;
821	    use std::fs::OpenOptions;
822	    use std::io;
823	    use std::os::raw::{c_int, c_void};
824	    use std::os::unix::io::{FromRawFd, RawFd};
825	    use std::process::Stdio;
826	
827	    unsafe extern "C" {
828	        fn pipe(pipefd: *mut RawFd) -> c_int;
829	        fn pipe2(pipefd: *mut RawFd, flags: c_int) -> c_int;
830	        fn read(fd: RawFd, buf: *mut c_void, count: usize) -> isize;
831	        fn close(fd: RawFd) -> c_int;
832	        fn fcntl(fd: RawFd, cmd: c_int, arg: c_int) -> c_int;
833	    }
834	
835	    /// 构造一个读端已经关闭的管道写端：子进程一写标准错误就收到 EPIPE，
836	    /// 模拟“错误提示交给管道而接收方已提前关闭”，且一个字节都送不出去。
837	    fn closed_pipe_stderr() -> Stdio {
838	        let mut fds: [RawFd; 2] = [-1, -1];
839	        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
840	        // 读端立即关闭（File 析构关闭该 fd）。
841	        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
842	        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
843	    }
844	
845	    /// 以只读方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
846	    /// 模拟“标准错误从一开始就被定向到拒绝写入的位置”。
847	    fn read_only_stderr(path: &Path) -> Stdio {
848	        let file = OpenOptions::new()
849	            .read(true)
850	            .write(false)
851	            .open(path)
852	            .expect("open read-only fd");
853	        Stdio::from(file)
854	    }
855	
856	    fn run_with_stderr(stderr: Stdio, args: &[&OsStr]) -> Output {
857	        inkseal()
858	            .args(args)
859	            .stdout(Stdio::piped())
860	            .stderr(stderr)
861	            .output()
862	            .expect("failed to run inkseal")
863	    }
864	
865	    /// 标准错误从第一个字节起就不可写时，所有用法错误仍以退出码 2
866	    /// 正常结束：不崩溃、不改报成功、不把用法说明挪到标准输出。
867	    #[test]
868	    fn usage_errors_with_dead_stderr_keep_exit_code_2() {
869	        let dir = TestDir::new("stderr-usage");
870	        let file = dir.write_file(OsStr::new("real.txt"), b"abc");
871	        let missing = dir.path().join("does-not-exist");
872	
873	        let cases: Vec<Vec<&OsStr>> = vec![
874	            vec![],                                              // 无参数
875	            vec![OsStr::new("frobnicate")],                     // 未知子命令
876	            vec![OsStr::new("digest")],                         // 缺少文件参数
877	            vec![
878	                OsStr::new("digest"),
879	                file.as_os_str(),
880	                OsStr::new("extra"),
881	            ],                                                   // 多给参数
882	            vec![OsStr::new("check-digest")],                   // 缺少两个参数
883	            vec![OsStr::new("check-digest"), file.as_os_str()], // 缺少摘要参数
884	            vec![
885	                // 非法摘要 + 不存在的文件：格式校验先于文件访问，
886	                // 即使格式提示无法写出，也必须是 2，且不去打开文件。
887	                OsStr::new("check-digest"),
888	                missing.as_os_str(),
889	                OsStr::new("abc"),
890	            ],
891	        ];
892	
893	        for args in cases {
894	            let output = run_with_stderr(closed_pipe_stderr(), &args);
895	            assert_eq!(
896	                output.status.code(),
897	                Some(2),
898	                "usage error must exit 2 even with dead stderr, args={args:?}: {output:?}"
899	            );
900	            // 必须是正常退出而非被信号终止（panic 会以 101 或 SIGABRT 结束）。
901	            assert!(output.status.code().is_some(), "must not be killed: {output:?}");
902	            assert!(
903	                output.stdout.is_empty(),
904	                "usage text must never move to stdout: {output:?}"
905	            );
906	            assert!(
907	                output.stderr.is_empty(),
908	                "dead pipe cannot carry any bytes: {output:?}"
909	            );
910	        }
911	    }
912	
913	    /// 文件无法打开、路径为目录和摘要不匹配在标准错误完全不可写时，
914	    /// 仍以退出码 1 正常结束；读取失败同理（见下方只读 fd 之外的情形）。
915	    #[test]
916	    fn io_and_mismatch_failures_with_dead_stderr_keep_exit_code_1() {
917	        let dir = TestDir::new("stderr-failure");
918	        let file = dir.write_file(OsStr::new("hello.txt"), b"abc");
919	        let missing = dir.path().join("nope.txt");
920	        let subdir = dir.path().join("a-directory");
921	        fs::create_dir_all(&subdir).unwrap();
922	        let empty_hex =
923	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
924	
925	        let cases: Vec<Vec<&OsStr>> = vec![
926	            vec![OsStr::new("digest"), missing.as_os_str()],
927	            vec![OsStr::new("digest"), subdir.as_os_str()],
928	            vec![
929	                OsStr::new("check-digest"),
930	                missing.as_os_str(),
931	                OsStr::new(ABC_HEX),
932	            ],
933	            vec![
934	                OsStr::new("check-digest"),
935	                subdir.as_os_str(),
936	                OsStr::new(ABC_HEX),
937	            ],
938	            vec![
939	                OsStr::new("check-digest"),
940	                file.as_os_str(),
941	                OsStr::new(empty_hex),
942	            ],
943	        ];
944	
945	        for args in cases {
946	            let output = run_with_stderr(closed_pipe_stderr(), &args);
947	            assert_eq!(
948	                output.status.code(),
949	                Some(1),
950	                "failure must keep exit 1 with dead stderr, args={args:?}: {output:?}"
951	            );
952	            assert!(
953	                output.stdout.is_empty(),
954	                "no success output may appear, args={args:?}: {output:?}"
955	            );
956	            assert!(output.stderr.is_empty(), "dead pipe carries no bytes: {output:?}");
957	        }
958	    }
959	
960	    /// 标准错误从一开始就拒绝写入（fd 以只读方式打开，内核直接拒绝）时，
961	    /// 同样保留退出码且静默结束。
962	    #[test]
963	    fn read_only_stderr_keeps_exit_codes_without_panic() {
964	        let dir = TestDir::new("stderr-readonly");
965	        let sink = dir.write_file(OsStr::new("sink"), b"");
966	        let missing = dir.path().join("nope.txt");
967	
968	        // 每次运行都需要一个新的只读 fd（Stdio 会消耗它）。
969	        let usage = run_with_stderr(
970	            read_only_stderr(&sink),
971	            &[OsStr::new("digest")],
972	        );
973	        assert_eq!(usage.status.code(), Some(2), "{usage:?}");
974	        assert!(usage.stdout.is_empty(), "{usage:?}");
975	
976	        let open_fail = run_with_stderr(
977	            read_only_stderr(&sink),
978	            &[OsStr::new("digest"), missing.as_os_str()],
979	        );
980	        assert_eq!(open_fail.status.code(), Some(1), "{open_fail:?}");
981	        assert!(open_fail.stdout.is_empty(), "{open_fail:?}");
982	        assert!(
983	            !String::from_utf8_lossy(&open_fail.stderr).contains("panicked"),
984	            "must not crash: {open_fail:?}"
985	        );
986	    }
987	
988	    /// 标准错误不可用本身不能使成功操作失败：版本查询、摘要计算、
989	    /// 核对通过仍照常把结果写到标准输出并以 0 退出。
990	    #[test]
991	    fn success_is_unaffected_when_stderr_is_dead() {
992	        let dir = TestDir::new("stderr-dead-success");
993	        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
994	
995	        let version = run_with_stderr(closed_pipe_stderr(), &[OsStr::new("--version")]);
996	        assert_eq!(version.status.code(), Some(0), "{version:?}");
997	        assert_eq!(version.stdout, b"inkseal 0.1.0\n", "{version:?}");
998	        assert!(version.stderr.is_empty());
999	
1000	        let digest = run_with_stderr(
1001	            closed_pipe_stderr(),
1002	            &[OsStr::new("digest"), path.as_os_str()],
1003	        );
1004	        assert_eq!(digest.status.code(), Some(0), "{digest:?}");
1005	        assert_eq!(digest.stdout, format!("{ABC_HEX}\n").as_bytes(), "{digest:?}");
1006	
1007	        let check = run_with_stderr(
1008	            closed_pipe_stderr(),
1009	            &[
1010	                OsStr::new("check-digest"),
1011	                path.as_os_str(),
1012	                OsStr::new(ABC_HEX),
1013	            ],
1014	        );
1015	        assert_eq!(check.status.code(), Some(0), "{check:?}");
1016	        assert_eq!(check.stdout, b"OK\n", "{check:?}");
1017	    }
1018	
1019	    /// 成功结果无法写到标准输出、且连输出失败提示也无法写到标准错误时，
1020	    /// 按既有规则以 1 静默结束：两个流都为空，也没有崩溃信息。
1021	    #[test]
1022	    fn undeliverable_success_with_both_streams_dead_is_silent_exit_1() {
1023	        let dir = TestDir::new("both-dead");
1024	        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
1025	
1026	        let cases: Vec<Vec<&OsStr>> = vec![
1027	            vec![OsStr::new("--version")],
1028	            vec![OsStr::new("digest"), path.as_os_str()],
1029	            vec![
1030	                OsStr::new("check-digest"),
1031	                path.as_os_str(),
1032	                OsStr::new(ABC_HEX),
1033	            ],
1034	        ];
1035	        for args in cases {
1036	            let output = inkseal()
1037	                .args(&args)
1038	                .stdout(closed_pipe_stderr())
1039	                .stderr(closed_pipe_stderr())
1040	                .output()
1041	                .expect("failed to run inkseal");
1042	            assert_eq!(output.status.code(), Some(1), "args={args:?}: {output:?}");
1043	            assert!(output.stdout.is_empty(), "args={args:?}: {output:?}");
1044	            assert!(output.stderr.is_empty(), "args={args:?}: {output:?}");
1045	        }
1046	    }
1047	
1048	    /// 管道只接收了提示的前几个字节、接收方便提前关闭时，子进程在后续
1049	    /// 写入上收到 EPIPE：已发出的字节保留，退出码仍为 1，进程正常结束。
1050	    ///
1051	    /// 确定性地制造“部分送达后失败”：把管道容量缩到一个页面（4096），
1052	    /// 再让提示本身远大于该容量（超长路径触发的文件错误）。内核对
1053	    /// 大于 PIPE_BUF 的阻塞写是非原子的——写满容量后子进程阻塞等待，
1054	    /// 此时关闭读端，剩余写入必然以 EPIPE 失败，而提示开头的字节已经
1055	    /// 送达。若提示仍经由 eprintln! 写出，子进程会 panic（101/信号）。
1056	    #[cfg(target_os = "linux")]
1057	    #[test]
1058	    fn partial_stderr_write_failure_keeps_exit_code_without_panic() {
1059	        const F_SETPIPE_SZ: c_int = 1024 + 7;
1060	        // arm64/x86-64 Linux 上 O_CLOEXEC 均为 02000000（八进制）。
1061	        const O_CLOEXEC: c_int = 0o2000000;
1062	
1063	        let dir = TestDir::new("stderr-partial");
1064	        // 单条错误提示远超 PIPE_BUF（4096）：含约 10000 字节的路径名。
1065	        // 该路径无法打开（ENAMETOOLONG），属于退出码 1 的文件访问失败。
1066	        let path = dir.path().join("A".repeat(10_000));
1067	
1068	        // pipe2(…, O_CLOEXEC) 至关重要：读端不能被子进程继承，否则测试
1069	        // 关闭自己的读端副本后子进程仍持有读端，会无限阻塞地写给自己。
1070	        let mut fds: [RawFd; 2] = [-1, -1];
1071	        assert_eq!(
1072	            unsafe { pipe2(fds.as_mut_ptr(), O_CLOEXEC) },
1073	            0,
1074	            "{}",
1075	            io::Error::last_os_error()
1076	        );
1077	        let set = unsafe { fcntl(fds[1], F_SETPIPE_SZ, 4096) };
1078	        assert!(set >= 0, "shrink pipe: {}", io::Error::last_os_error());
1079	
1080	        let write_end = unsafe { std::fs::File::from_raw_fd(fds[1]) };
1081	        let child = inkseal()
1082	            .args(["digest"])
1083	            .arg(path.as_os_str())
1084	            .stdout(Stdio::piped())
1085	            .stderr(Stdio::from(write_end))
1086	            .spawn()
1087	            .expect("failed to run inkseal");
1088	
1089	        // 子进程的首次写入已填满 4096 字节容量后阻塞；一次性取出这段
1090	        // 连续的提示前缀（在子进程补入更多字节之前读完）。
1091	        let mut prefix = vec![0u8; 4096];
1092	        read_full(fds[0], &mut prefix);
1093	        assert!(
1094	            prefix.starts_with(b"inkseal: cannot open '"),
1095	            "delivered prefix must be the real hint: {:?}",
1096	            String::from_utf8_lossy(&prefix[..40.min(prefix.len())])
1097	        );
1098	
1099	        // 接收方提前关闭：管道中已送达的提示前缀无需也无法补齐，
1100	        // 子进程剩余写入立即失败，但必须仍以退出码 1 正常结束。
1101	        assert_eq!(unsafe { close(fds[0]) }, 0);
1102	
1103	        let output = child.wait_with_output().expect("failed to wait");
1104	        assert_eq!(output.status.code(), Some(1), "{output:?}");
1105	        assert!(output.stdout.is_empty(), "{output:?}");
1106	        assert!(
1107	            !String::from_utf8_lossy(&output.stderr).contains("panicked"),
1108	            "must not crash: {output:?}"
1109	        );
1110	    }
1111	
1112	    /// 阻塞地从 fd 读满 `buf`，EINTR 立即重试。
1113	    #[cfg(target_os = "linux")]
1114	    fn read_full(fd: RawFd, mut buf: &mut [u8]) {
1115	        while !buf.is_empty() {
1116	            let n = unsafe { read(fd, buf.as_mut_ptr().cast::<c_void>(), buf.len()) };
1117	            assert!(n > 0, "read pipe: {}", io::Error::last_os_error());
1118	            let len = n as usize;
1119	            buf = &mut buf[len..];
1120	        }
1121	    }
1122	}
1123

