Design of the shim (C, compiled with cc at test time, cached in temp dir):

```c
#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef ssize_t (*write_fn)(int, const void *, size_t);
static write_fn real_write = NULL;

/* Script per fd via env:
   INKSEAL_SHIM_SCRIPT_1 / INKSEAL_SHIM_SCRIPT_2
   tokens separated by ',', consumed one per write() call on that fd:
     E   -> return -1 with errno=EINTR
     Z   -> return 0 (no progress)
     B   -> return -1 with errno=EIO (unrecoverable)
     N   -> pass through to real write (full)
     s<n> -> short write of at most n bytes: real_write(fd, buf, min(n,count))
   After tokens are exhausted, pass through.
   The consumed script is written back to the env var so the next call
   sees the remaining tokens.
*/
```

Implementation detail: getenv returns pointer into environ; we need to parse first token, then setenv with the remainder. setenv allocates; fine.

```c
static const char *next_token(int fd) {
    char name[32];
    snprintf(name, sizeof name, "INKSEAL_SHIM_SCRIPT_%d", fd);
    const char *script = getenv(name);
    if (!script || !*script) return NULL;
    const char *comma = strchr(script, ',');
    static char token[32];
    size_t len = comma ? (size_t)(comma - script) : strlen(script);
    if (len >= sizeof token) len = sizeof token - 1;
    memcpy(token, script, len);
    token[len] = 0;
    setenv(name, comma ? comma + 1 : "", 1);
    return token;
}

ssize_t write(int fd, const void *buf, size_t count) {
    if (!real_write) real_write = (write_fn)dlsym(RTLD_NEXT, "write");
    if (fd == 1 || fd == 2) {
        const char *tok = next_token(fd);
        if (tok) {
            if (tok[0] == 'E') { errno = EINTR; return -1; }
            if (tok[0] == 'Z') return 0;
            if (tok[0] == 'B') { errno = EIO; return -1; }
            if (tok[0] == 's') {
                long n = atol(tok + 1);
                if (n >= 0 && (size_t)n < count) count = (size_t)n;
                return real_write(fd, buf, count);
            }
            /* 'N' or unknown: pass through */
        }
    }
    return real_write(fd, buf, count);
}
```

