Shim logic:

```rust
const EINTR: i32 = 4;
const EIO: i32 = 5;

#[no_mangle]
pub unsafe extern "C" fn write(fd: c_int, buf: *const c_void, count: usize) -> isize {
    let real = match real_write() { Some(f) => f, None => return -1 };
    if fd == 1 || fd == 2 {
        if let Some(tok) = next_token(fd) {
            let t = tok.trim();
            if t == "E" {
                errno_set(EINTR);
                return -1;
            }
            if t == "Z" {
                return 0;
            }
            if t == "B" {
                errno_set(EIO);
                return -1;
            }
            if let Some(n) = t.strip_prefix('s').and_then(|r| r.parse::<usize>().ok()) {
                let short = n.min(count);
                return real(fd, buf, short);
            }
            // "N" 或未识别：原样透传
        }
    }
    real(fd, buf, count)
}
```

