Token parsing: script stored as Vec<u8> from env; next_token returns the token at current index and advances past comma.

```rust
unsafe fn script_for(fd: c_int) -> Option<&'static [u8]> {
    let slot = if fd == 1 { &mut SCRIPT_OUT } else { &mut SCRIPT_ERR };
    if slot.is_none() {
        let name = if fd == 1 { b"INKSEAL_SHIM_SCRIPT_OUT\0" } else { b"INKSEAL_SHIM_SCRIPT_ERR\0" };
        let p = getenv(name.as_ptr() as *const c_char);
        let v = if p.is_null() { Vec::new() } else {
            let mut len = 0; while *p.add(len) != 0 { len += 1; }
            std::slice::from_raw_parts(p as *const u8, len).to_vec()
        };
        *slot = Some(v);
    }
    slot.as_ref().map(|v| v.as_slice())
}

unsafe fn next_token(fd: c_int) -> Option<String> {
    let idx = if fd == 1 { &mut IDX_OUT } else { &mut IDX_ERR };
    let script = script_for(fd)?;
    if *idx >= script.len() { return None; }
    let rest = &script[*idx..];
    let end = rest.iter().position(|&b| b == b',').map(|p| *idx + p).unwrap_or(script.len());
    let tok = String::from_utf8_lossy(&script[*idx..end]).into_owned();
    *idx = if end < script.len() { end + 1 } else { script.len() };
    Some(tok)
}
```

